#pragma once

// What JusPrin tells its server each time it starts, and the install id it
// keeps for that. GUI-free; LaunchReport sends it.

#include <cstddef>
#include <string>

namespace Slic3r { class AppConfig; }

namespace Slic3r::GUI::JusPrin::Updates {

// A random id made the first time this install starts and kept in AppConfig.
// It names the install, not the person: nothing ties it to an account, and a
// fresh install makes a new one.
inline constexpr char        kInstallIdKey[]  = "jusprin_install_id";
inline constexpr std::size_t kInstallIdLength = 32; // lowercase hex digits

// The stored id, made and stored first when there is none or it is not an id.
std::string install_id(AppConfig& config);

// The body of the start report, as the server reads it: the install id, the
// app's version label and what the system calls itself.
std::string launch_report_body(const std::string& install_id, const std::string& app, const std::string& os);

} // namespace Slic3r::GUI::JusPrin::Updates

#include "LaunchRecord.hpp"

#include "libslic3r/AppConfig.hpp"

#include <nlohmann/json.hpp>

#include <algorithm>
#include <cctype>
#include <iomanip>
#include <random>
#include <sstream>

namespace Slic3r::GUI::JusPrin::Updates {

namespace {

bool is_install_id(const std::string& value)
{
    return value.size() == kInstallIdLength &&
           std::all_of(value.begin(), value.end(), [](unsigned char c) { return std::isdigit(c) || (c >= 'a' && c <= 'f'); });
}

std::string new_install_id()
{
    static std::mt19937_64                       engine(std::random_device{}());
    std::uniform_int_distribution<std::uint64_t> distribution;
    std::ostringstream                           out;
    out << std::hex << std::setfill('0') << std::setw(16) << distribution(engine) << std::setw(16) << distribution(engine);
    return out.str();
}

} // namespace

std::string install_id(AppConfig& config)
{
    const std::string stored = config.get(kInstallIdKey);
    if (is_install_id(stored))
        return stored;
    const std::string made = new_install_id();
    config.set(kInstallIdKey, made);
    return made;
}

std::string launch_report_body(const std::string& install_id, const std::string& app, const std::string& os)
{
    return nlohmann::json{{"install", install_id}, {"app", app}, {"os", os}}.dump();
}

} // namespace Slic3r::GUI::JusPrin::Updates

#pragma once

// Once per run, JusPrin tells its server that it started: its version, what
// the system calls itself, and the install id from LaunchRecord. Nothing
// about the person goes with it, and no token. The server counts installs
// and starts from these reports, so it can see how many downloads become a
// JusPrin that runs; the answer is ignored.

namespace Slic3r::GUI::JusPrin::Updates {

// Sends the report on first call; later calls in the same run do nothing.
// Stealth mode, which turns the app's own calls off, turns this off too.
void report_launch();

