class LaunchesTestCase(TestCase):
    def post(self, body):
        return Client().post(URL, data=body if isinstance(body, (str, bytes)) else json.dumps(body),
                             content_type='application/json', HTTP_USER_AGENT='JusPrin/2.0.0 OrcaSlicer/2.5.0')

    def test_a_start_is_one_row(self):
        self.assertEqual(self.post(REPORT).status_code, 204)
        launch = AppLaunch.objects.get()
        self.assertEqual((launch.install_id, launch.app, launch.os), (INSTALL, REPORT['app'], REPORT['os']))
        self.assertIsNotNone(launch.created_at)

    def test_every_start_of_an_install_counts(self):
        self.post(REPORT)
        self.post(REPORT)
        self.assertEqual(AppLaunch.objects.filter(install_id=INSTALL).count(), 2)

